@push('scripts')
<script>
(function(){
  function showPopup(uuid){document.getElementById('popup').style.display='block';}
  function hidePopup(){document.getElementById('popup').style.display='none';}
  function togglePanel(){var p=document.getElementById('panel');p.classList.toggle('open');}
  window.showPopup=showPopup;
  window.hidePopup=hidePopup;
  window.togglePanel=togglePanel;
  document.querySelectorAll('.mpc-chip').forEach(function(c){
    c.addEventListener('click',function(){
      document.querySelectorAll('.mpc-chip').forEach(function(x){x.classList.remove('on');});
      c.classList.add('on');
    });
  });
})();
</script>
@endpush
